      if (platformSet && !platformSet.has(String(fact.platform || ''))) return false;
      if (byDim.size > 0 && !factMatchesBreakdownFilters(fact, byDim)) return false;
      if (outIdx && !factMatchesOutside(fact, outside, outIdx)) return false;
      return true;
